        (argc == 5 && (!parse_bound(argv[2], 64, 1048576, &count) ||
         !parse_bound(argv[3], 1, 1024, &repeats) ||
         !parse_bound(argv[4], 1, 21, &trials))) ||
        (count & (count - 1)) != 0 ||
        count * repeats * trials * UINT64_C(12) > UINT64_C(2000000000)) {
