        !check(NULL, NULL, 0, 0, 0) ||
        !check(NULL, NULL, -1, 0, 0) ||
        !check(NULL, NULL, -2, 0, 0) ||
        !check(NULL, NULL, INT64_MIN, 0, 0) ||
        !physical()) return 1;
    puts("performance physical and fixed cases passed: 11");
    return 0;
}

